    'New Santiago',
    city_id,
    NULL
FROM cities c
JOIN provinces p ON c.province_id = p.province_id
WHERE c.city_name = 'Asuncion'
AND p.province_name = 'Davao del Norte'
ON DUPLICATE KEY UPDATE zip_code = VALUES(zip_code);

