    'Magsaysay Hills',
    city_id,
    NULL
FROM cities c
JOIN provinces p ON c.province_id = p.province_id
WHERE c.city_name = 'Bambang'
AND p.province_name = 'Nueva Vizcaya'
ON DUPLICATE KEY UPDATE zip_code = VALUES(zip_code);

