    'Zone I Fatima',
    city_id,
    NULL
FROM cities c
JOIN provinces p ON c.province_id = p.province_id
WHERE c.city_name = 'Del Gallego'
AND p.province_name = 'Camarines Sur'
ON DUPLICATE KEY UPDATE zip_code = VALUES(zip_code);

