    city_id,
    NULL
FROM cities c
JOIN provinces p ON c.province_id = p.province_id
WHERE c.city_name = 'Pres. Manuel A. Roxas'
AND p.province_name = 'Zamboanga del Norte'
ON DUPLICATE KEY UPDATE zip_code = VALUES(zip_code);

